-- SPIKE: runtime PNG -> texture on the client
local B64 = ""
local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map = {}
for i = 1, 64 do map[chars:sub(i, i)] = i - 1 end
local name = "zmcp_spike_snail.png"
local out = getFileOutput(name)
local n, buf, bits = 0, 0, 0
for i = 1, #B64 do
    local v = map[B64:sub(i, i)]
    if v then
        buf = buf * 64 + v; bits = bits + 6
        if bits >= 8 then
            bits = bits - 8
            local byte = math.floor(buf / 2 ^ bits) % 256
            out:writeByte(byte); n = n + 1
            buf = buf % (2 ^ bits)
        end
    end
end
endFileOutput()
local sep = getFileSeparator()
local path = getMyDocumentFolder() .. sep .. "Lua" .. sep .. name
local tex = getTexture(path)
local how = "getTexture"
if not tex then
    local ok, t = pcall(function() return Texture.new(path) end)
    if ok and t then tex = t; how = "Texture.new" end
end
VappsClient.spikeTex = tex
VappsClient.renderHooks["spike"] = function(ui)
    if tex then ui:drawTextureScaled(tex, 120, 160, 320, 256, 1, 1, 1, 1) end
end
return "bytes=" .. n .. " via=" .. how .. " tex=" .. tostring(tex) .. " size=" .. (tex and (tex:getWidth() .. "x" .. tex:getHeight()) or "-")
